require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/epic_turn.json
# is EpicTurn.mayStart for a linear Epic of three children, every state of each
# child's implementation Workflow and every queued candidate, generated by
# `lake exe syrus_fixtures epic_turn`. This builds the same Epic and runs the
# real StepDispatcher.epic_sibling_blocking?, which must block exactly when the
# model says the candidate may not start. The fixture has no Job dependencies;
# the Ruby's skip of a queued child waiting on a queued sibling is not modelled.
RSpec.describe "EpicTurn model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/epic_turn.json").read)
  let(:user) { Factories.user }
  let(:repository) { Factories.repository(user: user) }
  let(:epic) { Factories.epic(user: user, repository: repository, epic_dependency_policy: "linear") }

  it "covers every state of three children and every queued candidate" do
    expect(fixture.fetch("cases").size).to eq(48)
  end

  fixture.fetch("cases").each do |example|
    states, candidate, may_start = example.values_at("states", "candidate", "may_start")

    it "#{may_start ? 'lets' : 'stops'} child #{candidate} start when the children are #{states.join(', ')}" do
      created = Time.zone.parse("2026-11-23 10:00:00")
      workflows = states.each_with_index.map do |state, index|
        job = Factories.job_record(user: user, repository: repository, epic: epic, issue_number: 100 + index)
        Workflow.create!(job: job, trigger_kind: "initial", state: state, created_at: created + index.minutes)
      end

      expect(StepDispatcher.epic_sibling_blocking?(workflows.fetch(candidate))).to eq(!may_start)
    end
  end
end
